insert into public.settings (key, value)
values (
  'home_faq',
  '[{"q_ar":"هل الفنيون من فريقكم أم من جهات خارجية؟","a_ar":"جميع الفنيين من فريقنا ويعملون معنا يوميًا، وعددهم أكثر من 10 فنيين.","q_en":"Are the technicians your own staff?","a_en":"Yes. Every technician is part of our own team — more than 10 of them work with us every day."},{"q_ar":"كيف أعرف السعر قبل بدء العمل؟","a_ar":"أرسل لنا الخدمة المطلوبة عبر واتساب، ويُفضّل مع صورة، ونؤكد لك السعر والموعد قبل أن يبدأ الفني.","q_en":"How do I know the price before work starts?","a_en":"Send us the service you need on WhatsApp, ideally with a photo, and we confirm the price and time before the technician starts."},{"q_ar":"هل تحضرون القطع معكم؟","a_ar":"نعم، معظم القطع متوفرة في محلنا بحي غرناطة، فيحضرها الفني معه وينتهي العمل غالبًا في زيارة واحدة.","q_en":"Do you bring the parts?","a_en":"Yes. Most parts are in stock at our shop in Ghirnatah, so the technician brings them along and the job is usually done in one visit."},{"q_ar":"هل تعملون في الطوارئ وأيام الجمعة؟","a_ar":"نعم، خدمة الطوارئ متاحة على مدار الساعة طوال أيام الأسبوع بما فيها الجمعة، ومواعيد المحل موضحة أسفل الصفحة.","q_en":"Do you handle emergencies and work on Fridays?","a_en":"Yes. Emergency service is available 24/7, Fridays included. The shop opening hours are at the bottom of the page."},{"q_ar":"ما الأحياء التي تخدمونها؟","a_ar":"غرناطة، قرطبة، الشهداء، الحمراء، اليرموك، الفلاح، الازدهار، التعاون، الوادي والأحياء المجاورة، والأحياء الأبعد حسب نوع العمل.","q_en":"Which districts do you cover?","a_en":"Ghirnatah, Qurtubah, Ash Shuhada, Al Hamra, Al Yarmuk, Al Falah, Al Izdihar, At Taawun, Al Wadi and nearby districts — farther areas depending on the job."}]'::jsonb
)
