insert into public.categories (slug, name_ar, name_en, headline_ar, headline_en, intro_ar, intro_en, meta_description_ar, meta_description_en, covers_ar, covers_en, faq, icon, image_url, wa_message_ar, wa_message_en, sort_order, is_active, is_primary)
values (
  'plumbing',
  'السباكة',
  'Plumbing',
  'سباك في الرياض — غرناطة والأحياء المجاورة',
  'Plumber in Riyadh — Ghirnatah and nearby districts',
  'خدمات سباكة في الرياض ينفذها فنيون من فريقنا، ومعهم القطع من محلنا في غرناطة: تركيب السخانات والخلاطات، وتغيير المحابس، وتسليك الانسدادات. نؤكد لك السعر عبر واتساب قبل البدء، وخدمة الطوارئ متاحة على مدار الساعة.',
  'Plumbing services in Riyadh by our own technicians, with parts from our shop in Ghirnatah: water heaters, mixer taps, valves and blockage clearing. We confirm the price on WhatsApp before we start, and emergency service is available 24/7.',
  'سباك في الرياض من فريقنا: تركيب سخانات وخلاطات وتسليك انسدادات، والقطع من محلنا في غرناطة. السعر عبر واتساب وخدمة طوارئ 24/7.',
  'Plumber in Riyadh from our own team: water heaters, mixers and blockage clearing, with parts from our Ghirnatah shop. Price on WhatsApp, 24/7 emergency.',
  array['تركيب وتغيير السخانات العادية والمخفية', 'تغيير الخلاطات والشطافات والمحابس', 'تسليك انسداد المغاسل والأحواض والصرف', 'تركيب المغاسل والكراسي والدشات', 'المضخات والغطاسات وعوامات الخزانات', 'تمديد وتوصيل الغسالات']::text[],
  array['Standard and concealed water heaters', 'Mixer taps, bidet sprayers and valves', 'Sink, basin and drain blockages', 'Basins, toilets and showers', 'Water pumps, submersible pumps and tank float valves', 'Washing machine connections']::text[],
  '[{"q_ar":"متى يصل السباك؟","a_ar":"نحدد الموعد معك عبر واتساب حسب جدول الفنيين، وفي الحالات الطارئة مثل التسريب الكبير نرسل فنيًا في أقرب وقت على مدار الساعة.","q_en":"When can the plumber come?","a_en":"We agree the time with you on WhatsApp based on the technicians’ schedule. For emergencies such as a major leak, we send a technician as soon as possible, day or night."},{"q_ar":"هل القطع متوفرة لديكم؟","a_ar":"نعم، معظم قطع السباكة من سخانات وخلاطات ومحابس ولّيات متوفرة في محلنا بغرناطة، فيحضرها الفني معه وينتهي العمل غالبًا في زيارة واحدة.","q_en":"Do you have the parts?","a_en":"Yes. Most plumbing parts — heaters, mixers, valves and hoses — are in stock at our Ghirnatah shop, so the technician brings them and the job is usually done in one visit."},{"q_ar":"كيف أعرف السعر؟","a_ar":"أرسل لنا الخدمة المطلوبة عبر واتساب، ويُفضّل مع صورة، ونؤكد لك السعر قبل بدء العمل.","q_en":"How do I get the price?","a_en":"Send us the service you need on WhatsApp, ideally with a photo, and we confirm the price before any work starts."}]'::jsonb,
  'droplet',
  '/illustrations/plumbing.png',
  'السلام عليكم، أحتاج فني سباكة.',
  'Hello, I need a plumber.',
  10,
  true,
  true
)
on conflict (slug) do nothing;

insert into public.categories (slug, name_ar, name_en, headline_ar, headline_en, intro_ar, intro_en, meta_description_ar, meta_description_en, covers_ar, covers_en, faq, icon, image_url, wa_message_ar, wa_message_en, sort_order, is_active, is_primary)
values (
  'electrical',
  'الكهرباء والإنارة',
  'Electrical & Lighting',
  'كهربائي في الرياض — غرناطة والأحياء المجاورة',
  'Electrician in Riyadh — Ghirnatah and nearby districts',
  'خدمات كهرباء وإنارة في الرياض ينفذها فنيون من فريقنا، ومعهم القطع من محلنا في غرناطة: سبوت لايت وبانيل ولمبات، وأفياش ومفاتيح، وطبلونات. نؤكد لك السعر عبر واتساب قبل البدء، وخدمة الطوارئ متاحة على مدار الساعة.',
  'Electrical and lighting services in Riyadh by our own technicians, with parts from our shop in Ghirnatah: spotlights, panel lights and bulbs, sockets and switches, and breaker panels. We confirm the price on WhatsApp before we start, and emergency service is available 24/7.',
  'كهربائي في الرياض من فريقنا: سبوت لايت وأفياش وطبلونات وفحص أعطال، والقطع من محلنا في غرناطة. السعر عبر واتساب وخدمة طوارئ 24/7.',
  'Electrician in Riyadh from our own team: spotlights, sockets, panels and fault finding, with parts from our Ghirnatah shop. Price on WhatsApp, 24/7.',
  array['تركيب وتغيير السبوت لايت والبانيل واللمبات', 'الأفياش ومفاتيح المكيفات والسخانات', 'مفاتيح الطبلون الرئيسي والفرعي وفحص الأعطال', 'الثريات وأشرطة الليد المخفية', 'الإنارة الخارجية والكشافات وأعمدة الإنارة', 'الشفاطات وأجراس الأبواب وتمديدات الغسالات']::text[],
  array['Spotlights, panel lights and bulbs', 'Sockets and AC / water heater switches', 'Main and sub-panel breakers, fault finding', 'Chandeliers and hidden LED strips', 'Outdoor lights, flood lights and pole lights', 'Exhaust fans, doorbells and washer power points']::text[],
  '[{"q_ar":"المفتاح في الطبلون يفصل باستمرار، ماذا أفعل؟","a_ar":"لا تحاول تشغيله مرارًا. افصل الأجهزة عن الخط وتواصل معنا، ويفحص الفني سبب الفصل سواء كان حملًا زائدًا أو تماسًا أو مفتاحًا ضعيفًا.","q_en":"A breaker keeps tripping. What should I do?","a_en":"Don’t keep switching it back on. Unplug the devices on that line and contact us; the technician will find whether it’s an overload, a short or a weak breaker."},{"q_ar":"هل توفرون السبوت لايت والبانيل؟","a_ar":"نعم، السبوت لايت والبانيل واللمبات بمقاسات وألوان إضاءة مختلفة متوفرة في محلنا، ويحضرها الفني معه حسب طلبك.","q_en":"Do you supply the spotlights and panel lights?","a_en":"Yes. Spotlights, panel lights and bulbs in many sizes and light colours are in stock at our shop, and the technician brings what you need."},{"q_ar":"كيف أعرف السعر؟","a_ar":"أرسل لنا الخدمة والعدد أو المقاس عبر واتساب، ويُفضّل مع صورة، ونؤكد لك السعر قبل بدء العمل.","q_en":"How do I get the price?","a_en":"Send us the service and the quantity or size on WhatsApp, ideally with a photo, and we confirm the price before any work starts."}]'::jsonb,
  'zap',
  '/illustrations/electrical.png',
  'السلام عليكم، أحتاج فني كهرباء.',
  'Hello, I need an electrician.',
  20,
  true,
  true
)
on conflict (slug) do nothing;

insert into public.categories (slug, name_ar, name_en, headline_ar, headline_en, intro_ar, intro_en, meta_description_ar, meta_description_en, covers_ar, covers_en, faq, icon, image_url, wa_message_ar, wa_message_en, sort_order, is_active, is_primary)
values (
  'cctv-intercom-network',
  'الكاميرات والإنتركم والشبكات',
  'CCTV, Intercom & Network',
  'تركيب كاميرات مراقبة وإنتركم في الرياض',
  'CCTV and intercom installation in Riyadh',
  'تركيب كاميرات المراقبة والإنتركم وتقوية الشبكات في الرياض بأيدي فنيين من فريقنا. نركّب جميع الأنواع حسب اختيار العميل، ونضبط التشغيل على جوالك قبل أن نغادر، ونؤكد لك السعر عبر واتساب قبل البدء.',
  'CCTV, intercom and home network installation in Riyadh by our own technicians. We install all types according to the customer’s choice, set everything up on your phone before we leave, and confirm the price on WhatsApp before we start.',
  'تركيب كاميرات مراقبة وإنتركم وتقوية شبكات في الرياض بأيدي فنيين من فريقنا، جميع الأنواع حسب اختيارك. السعر عبر واتساب.',
  'CCTV, intercom and Wi-Fi installation in Riyadh by our own technicians — all types, your choice of brand. Price confirmed on WhatsApp before work starts.',
  array['كاميرات المراقبة الداخلية والخارجية', 'كاميرات الأبواب والإنتركم: تركيب وإصلاح وتغيير', 'فحص ضعف الشبكة وتركيب الراوتر والمقويات', 'تمديد كابلات الشبكة وأجهزة الواي فاي', 'أنظمة التلفزيون والسماعات والسنترال', 'أنظمة المساعدة لذوي الاحتياجات الخاصة']::text[],
  array['Indoor and outdoor security cameras', 'Door cameras and intercoms: install, repair, replace', 'Weak network checks, routers and extenders', 'Network cabling and Wi-Fi devices', 'TV, speaker and PBX systems', 'Assistance systems for people with special needs']::text[],
  '[{"q_ar":"ما أنواع الكاميرات التي تركبونها؟","a_ar":"نركّب جميع الأنواع حسب اختيار العميل، ويمكننا أن نقترح عليك الأنسب لمساحة البيت وعدد المداخل.","q_en":"Which camera brands do you install?","a_en":"All brands, according to the customer’s choice. We can also suggest what suits the size of your home and the number of entrances."},{"q_ar":"هل أستطيع مشاهدة الكاميرات من جوالي؟","a_ar":"نعم، نضبط التطبيق على جوالك قبل أن نغادر ونشرح لك طريقة المشاهدة والرجوع إلى التسجيلات.","q_en":"Can I watch the cameras on my phone?","a_en":"Yes. We set up the app on your phone before we leave and show you how to view live video and recordings."},{"q_ar":"كيف أعرف السعر؟","a_ar":"أرسل لنا عدد الكاميرات أو نوع الخدمة وصورًا للمكان عبر واتساب، ونؤكد لك السعر قبل بدء العمل.","q_en":"How do I get the price?","a_en":"Send us the number of cameras or the service you need, with photos of the place, on WhatsApp and we confirm the price before work starts."}]'::jsonb,
  'cctv',
  '/illustrations/cctv-intercom-network.png',
  'السلام عليكم، أحتاج فني كاميرات وإنتركم وشبكات.',
  'Hello, I need a CCTV, intercom and network technician.',
  30,
  true,
  true
)
on conflict (slug) do nothing;

insert into public.categories (slug, name_ar, name_en, headline_ar, headline_en, intro_ar, intro_en, meta_description_ar, meta_description_en, covers_ar, covers_en, faq, icon, image_url, wa_message_ar, wa_message_en, sort_order, is_active, is_primary)
values (
  'painting',
  'الدهانات',
  'Painting',
  'دهانات داخلية وخارجية في الرياض',
  'Interior and exterior painting in Riyadh',
  'دهان الجدران الداخلية والواجهات الخارجية للشقق والفلل في الرياض. نحمي الأرضيات والأثاث قبل البدء، ونجهّز الجدار ونعالج الشقوق البسيطة قبل الدهان، ونؤكد لك السعر عبر واتساب بعد معرفة المساحة.',
  'Interior wall and exterior facade painting for apartments and villas in Riyadh. We protect floors and furniture first, prepare the walls and fill minor cracks before painting, and confirm the price on WhatsApp once we know the area.',
  'دهانات داخلية وخارجية للشقق والفلل في الرياض مع تجهيز الجدران وحماية الأرضيات. السعر عبر واتساب بعد معرفة المساحة.',
  'Interior and exterior painting for apartments and villas in Riyadh, with wall preparation and floor protection. Price on WhatsApp once we know the area.',
  array['تجهيز الجدران ومعالجة الشقوق البسيطة', 'دهانات داخلية للغرف والصالات', 'دهانات خارجية للواجهات والأسوار', 'حماية الأرضيات والأثاث أثناء العمل']::text[],
  array['Wall preparation and minor crack filling', 'Interior painting for rooms and halls', 'Exterior painting for facades and boundary walls', 'Floor and furniture protection while we work']::text[],
  '[{"q_ar":"هل توفرون الدهان أم أشتريه بنفسي؟","a_ar":"يمكنك اختيار الدهان بنفسك، أو نخبرك بالكمية المناسبة لمساحتك قبل البدء.","q_en":"Do you supply the paint or should I buy it?","a_en":"You can choose the paint yourself, or we tell you the right quantity for your area before we start."}]'::jsonb,
  'paint-roller',
  '/illustrations/painting.png',
  'السلام عليكم، أحتاج خدمة دهانات.',
  'Hello, I need a painting service.',
  40,
  true,
  false
)
on conflict (slug) do nothing;

insert into public.categories (slug, name_ar, name_en, headline_ar, headline_en, intro_ar, intro_en, meta_description_ar, meta_description_en, covers_ar, covers_en, faq, icon, image_url, wa_message_ar, wa_message_en, sort_order, is_active, is_primary)
values (
  'tiles',
  'البلاط',
  'Tiles',
  'تركيب بلاط في الرياض',
  'Tile installation in Riyadh',
  'تركيب بلاط الأرضيات والجدران، أو تكسير البلاط القديم وتركيب بلاط جديد مكانه، للمطابخ والحمامات والغرف. نحدد معك المساحة ونوع العمل عبر واتساب، ونؤكد لك السعر قبل البدء.',
  'Floor and wall tiling, or removing old tiles and laying new ones, for kitchens, bathrooms and rooms. We agree the area and type of work with you on WhatsApp and confirm the price before we start.',
  'تركيب بلاط أرضيات وجدران في الرياض، وتكسير البلاط القديم وتركيب جديد للمطابخ والحمامات والغرف. السعر عبر واتساب.',
  'Floor and wall tile installation in Riyadh, including removing old tiles and laying new ones for kitchens, bathrooms and rooms. Price on WhatsApp.',
  array['تركيب بلاط أرضيات جديد', 'تكسير البلاط القديم وتركيب جديد', 'بلاط جدران المطابخ والحمامات', 'ضبط المستوى والميول والترويب']::text[],
  array['New floor tiles', 'Old tile removal and new tiling', 'Kitchen and bathroom wall tiles', 'Levelling, falls and grouting']::text[],
  '[{"q_ar":"هل توفرون البلاط؟","a_ar":"يمكنك اختيار البلاط بنفسك، ونخبرك بالكمية المناسبة بعد معرفة المساحة.","q_en":"Do you supply the tiles?","a_en":"You can choose the tiles yourself, and we tell you the quantity you need once we know the area."}]'::jsonb,
  'grid',
  '/illustrations/tiles.png',
  'السلام عليكم، أحتاج فني تركيب بلاط.',
  'Hello, I need a tile installer.',
  50,
  true,
  false
)
on conflict (slug) do nothing;

insert into public.categories (slug, name_ar, name_en, headline_ar, headline_en, intro_ar, intro_en, meta_description_ar, meta_description_en, covers_ar, covers_en, faq, icon, image_url, wa_message_ar, wa_message_en, sort_order, is_active, is_primary)
values (
  'cleaning',
  'التنظيف',
  'Cleaning',
  'تنظيف المنازل والخزانات في الرياض',
  'Home and water tank cleaning in Riyadh',
  'تنظيف الخزانات الأرضية والعلوية، وتنظيف الشقق والفلل الجديدة والمفروشة، وإزالة بقع الدهان وغراء الموكيت من الأرضيات. نحدد معك نوع التنظيف والمساحة عبر واتساب، ونؤكد لك السعر قبل البدء.',
  'Ground and roof water tank cleaning, new and furnished apartment and villa cleaning, and removing paint stains and carpet glue from floors. We agree the type of cleaning and the area on WhatsApp and confirm the price before we start.',
  'تنظيف الخزانات والشقق والفلل في الرياض، وإزالة بقع الدهان وغراء الموكيت من الأرضيات. السعر عبر واتساب قبل البدء.',
  'Water tank, apartment and villa cleaning in Riyadh, plus paint stain and carpet glue removal from floors. Price confirmed on WhatsApp before we start.',
  array['تنظيف الخزانات الأرضية والعلوية', 'تنظيف الشقق والفلل الجديدة والمفروشة', 'إزالة بقع الدهان من الأرضيات', 'إزالة غراء الموكيت']::text[],
  array['Ground and roof water tanks', 'New and furnished apartments and villas', 'Paint stain removal from floors', 'Carpet glue removal']::text[],
  '[{"q_ar":"كم مرة يُنصح بتنظيف خزان الماء؟","a_ar":"يُنصح بتنظيف الخزان مرة أو مرتين في السنة على الأقل، أو عند ملاحظة رواسب أو تغيّر في لون الماء.","q_en":"How often should a water tank be cleaned?","a_en":"At least once or twice a year, or whenever you notice sediment or a change in the water’s colour."}]'::jsonb,
  'sparkles',
  '/illustrations/cleaning.png',
  'السلام عليكم، أحتاج خدمة تنظيف.',
  'Hello, I need a cleaning service.',
