insert into public.services (category_id, slug, name_ar, name_en, short_ar, short_en, body_ar, body_en, includes_ar, includes_en, excludes_ar, excludes_en, options_ar, options_en, parts_ar, parts_en, parts_in_stock, wa_message_ar, wa_message_en, image_url, faq, has_detail_page, featured, sort_order, is_active)
values (
  (select id from public.categories where slug = 'plumbing'),
  'new-water-heater-installation',
  'تركيب سخان جديد',
  'New water heater installation',
  'تركيب سخان كهربائي جديد على الجدار وتوصيله بالماء والكهرباء، مع تجربة التشغيل.',
  'Wall-mounting a new electric water heater and connecting it to water and power, then testing it.',
  'نركّب لك سخانًا كهربائيًا جديدًا على الجدار، ونوصله بمواسير الماء البارد والحار وبالكهرباء بشكل آمن. يحضر الفني السخان والوصلات من محلنا إن رغبت، أو يركّب السخان الذي اشتريته.

قبل التركيب نتأكد من قوة الجدار ومكان المفتاح والتمديدات الموجودة، وبعد التركيب نملأ السخان ونشغّله ونفحص التسريب.

أرسل لنا سعة السخان المطلوبة ومكان التركيب عبر واتساب، ونؤكد لك السعر قبل البدء.',
  'We wall-mount a new electric water heater and connect it safely to the cold and hot water lines and to power. The technician can bring the heater and fittings from our shop, or install one you have already bought.

Before installing we check the wall, the switch position and the existing pipework; afterwards we fill the heater, switch it on and check for leaks.

Send us the heater size you want and where it goes on WhatsApp, and we confirm the price before we start.',
  array['تثبيت السخان على الجدار بحوامل مناسبة', 'توصيل الماء البارد والحار', 'تركيب محبس وصمام أمان عند الحاجة', 'التوصيل بالكهرباء وتجربة التشغيل', 'فحص التسريب بعد التعبئة']::text[],
  array['Fixing the heater to the wall on suitable brackets', 'Cold and hot water connections', 'Isolation valve and safety valve where needed', 'Power connection and test run', 'Leak check after filling']::text[],
  array['تمديدات مياه جديدة لمسافات طويلة', 'تمديد خط كهرباء جديد من الطبلون', 'أعمال الجبس والبلاط والدهان']::text[],
  array['New water pipe runs over long distances', 'A new power line from the breaker panel', 'Gypsum, tiling or painting work']::text[],
  '{}'::text[],
  '{}'::text[],
  array['سخانات كهربائية بسعات مختلفة', 'وصلات ولّيات مرنة', 'محابس وصمامات أمان', 'حوامل وبراغي تثبيت']::text[],
  array['Electric water heaters in different sizes', 'Fittings and flexible hoses', 'Valves and safety valves', 'Brackets and fixings']::text[],
  true,
  null,
  null,
  null,
  '[{"q_ar":"هل يمكن أن أشتري السخان بنفسي؟","a_ar":"نعم، يركّبه الفني لك، أو يمكنك اختيار سخان من محلنا ويحضره الفني معه.","q_en":"Can I buy the heater myself?","a_en":"Yes, the technician will install it for you — or choose one from our shop and the technician brings it along."},{"q_ar":"كم يستغرق تركيب السخان؟","a_ar":"غالبًا من ساعة إلى ساعتين، حسب المكان والتمديدات الموجودة.","q_en":"How long does installation take?","a_en":"Usually one to two hours, depending on the location and the existing pipework."}]'::jsonb,
  true,
  true,
  10,
  true
)
on conflict (category_id, slug) do nothing;

insert into public.services (category_id, slug, name_ar, name_en, short_ar, short_en, body_ar, body_en, includes_ar, includes_en, excludes_ar, excludes_en, options_ar, options_en, parts_ar, parts_en, parts_in_stock, wa_message_ar, wa_message_en, image_url, faq, has_detail_page, featured, sort_order, is_active)
values (
  (select id from public.categories where slug = 'plumbing'),
  'new-concealed-water-heater-installation',
  'تركيب سخان مخفي جديد',
  'New concealed water heater installation',
  'تركيب سخان مخفي جديد فوق السقف المستعار أو داخل فتحة الصيانة، مع التوصيل والتجربة.',
  'Installing a new concealed heater above the false ceiling or in the access hatch, connected and tested.',
  'السخان المخفي يُركّب فوق السقف المستعار (الجبس) أو داخل فتحة صيانة، فيبقى الحمام مرتبًا دون سخان ظاهر. نركّبه ونوصله بالماء والكهرباء ونجرّبه قبل إغلاق الفتحة.

نتأكد من وجود فتحة صيانة مناسبة يسهل الوصول منها إلى السخان لاحقًا، ومن تثبيته على قاعدة أو حوامل قوية.

أرسل لنا صورة للسقف أو فتحة الصيانة عبر واتساب، ونؤكد لك السعر قبل البدء.',
  'A concealed heater sits above the false (gypsum) ceiling or inside an access hatch, so the bathroom stays tidy with no visible heater. We install it, connect water and power, and test it before closing the hatch.

We make sure there is a suitable access hatch so the heater can be reached later, and that it rests on a solid base or strong brackets.

Send us a photo of the ceiling or access hatch on WhatsApp, and we confirm the price before we start.',
  array['تثبيت السخان فوق السقف على قاعدة أو حوامل', 'توصيل الماء البارد والحار', 'التوصيل بالكهرباء وتجربة التشغيل', 'فحص التسريب قبل إغلاق الفتحة']::text[],
  array['Fixing the heater above the ceiling on a base or brackets', 'Cold and hot water connections', 'Power connection and test run', 'Leak check before the hatch is closed']::text[],
  array['عمل فتحة جديدة في الجبس أو إصلاحه', 'تمديد خط كهرباء جديد من الطبلون']::text[],
  array['Cutting a new gypsum opening or repairing gypsum', 'A new power line from the breaker panel']::text[],
  '{}'::text[],
  '{}'::text[],
  array['سخانات مخفية بسعات مختلفة', 'وصلات ولّيات مرنة', 'محابس وصمامات أمان']::text[],
  array['Concealed heaters in different sizes', 'Fittings and flexible hoses', 'Valves and safety valves']::text[],
  true,
  null,
  null,
  null,
  '[{"q_ar":"هل أحتاج فتحة في السقف؟","a_ar":"نعم، يحتاج السخان المخفي فتحة صيانة للوصول إليه. إن لم تكن موجودة، أخبرنا عبر واتساب لنرتب ذلك معك.","q_en":"Do I need an opening in the ceiling?","a_en":"Yes, a concealed heater needs an access hatch. If you don’t have one, tell us on WhatsApp and we’ll arrange it with you."}]'::jsonb,
  true,
  true,
  20,
  true
)
on conflict (category_id, slug) do nothing;

