insert into public.services (category_id, slug, name_ar, name_en, short_ar, short_en, body_ar, body_en, includes_ar, includes_en, excludes_ar, excludes_en, options_ar, options_en, parts_ar, parts_en, parts_in_stock, wa_message_ar, wa_message_en, image_url, faq, has_detail_page, featured, sort_order, is_active)
values (
  (select id from public.categories where slug = 'plumbing'),
  'sink-basin-blockage-clearing',
  'تسليك انسداد الحوض والمغسلة',
  'Sink & basin blockage clearing',
  'تسليك انسداد المغسلة أو حوض المطبخ بالأدوات المناسبة دون تكسير.',
  'Clearing blocked basins and kitchen sinks with the right tools, without breaking anything.',
  'نسلّك انسداد المغسلة وحوض المطبخ الناتج عن الدهون أو الشعر أو بقايا الطعام، باستخدام أدوات التسليك المناسبة دون تكسير.

نفك السيفون وننظفه إذا لزم، ثم نختبر سرعة تصريف الماء قبل أن نغادر.

وإذا تكرر الانسداد، نفحص خط الصرف ونخبرك بالسبب والحل.',
  'We clear basin and kitchen sink blockages caused by grease, hair or food waste, using the right drain tools — no breaking.

We take the trap apart and clean it if needed, then test how fast the water drains before we leave.

If the blockage keeps coming back, we check the drain line and tell you the cause and the fix.',
  array['فك السيفون وتنظيفه', 'تسليك الخط بالأدوات المناسبة', 'اختبار التصريف بعد التسليك']::text[],
  array['Removing and cleaning the trap', 'Clearing the line with the right tools', 'Drain test afterwards']::text[],
  array['تكسير البلاط أو الجدار لتغيير المواسير', 'تسليك خطوط الصرف الرئيسية (خدمة تسليك الصرف)']::text[],
  array['Breaking tiles or walls to replace pipes', 'Main drain lines (see Drain blockage clearing)']::text[],
  '{}'::text[],
  '{}'::text[],
  array['سيفونات وهرابات مغاسل', 'جلب وحلقات إحكام']::text[],
  array['Traps and basin wastes', 'Washers and seals']::text[],
  true,
  null,
  null,
  null,
  '[{"q_ar":"هل تستخدمون مواد كيميائية؟","a_ar":"نعتمد أولًا على الأدوات الميكانيكية لأنها أكثر أمانًا للمواسير، ولا نستخدم مواد قوية إلا عند الحاجة وبعد إخبارك.","q_en":"Do you use chemicals?","a_en":"We use mechanical tools first because they are safer for your pipes, and only use strong products when needed and after telling you."}]'::jsonb,
  true,
  true,
  120,
  true
)
on conflict (category_id, slug) do nothing;

insert into public.services (category_id, slug, name_ar, name_en, short_ar, short_en, body_ar, body_en, includes_ar, includes_en, excludes_ar, excludes_en, options_ar, options_en, parts_ar, parts_en, parts_in_stock, wa_message_ar, wa_message_en, image_url, faq, has_detail_page, featured, sort_order, is_active)
values (
  (select id from public.categories where slug = 'plumbing'),
  'drain-blockage-clearing',
  'تسليك انسداد الصرف',
  'Drain blockage clearing',
  'تسليك انسداد صرف الحمامات والمطابخ والصفايات الأرضية وخطوط الصرف.',
  'Clearing blocked bathroom, kitchen, floor and main drain lines.',
  'نسلّك انسداد صرف الحمامات والمطابخ والصفايات الأرضية، والخطوط بين الغرف وحتى غرفة التفتيش، باستخدام أدوات ومكائن التسليك.

نحدد مكان الانسداد أولًا، ثم نسلّكه ونختبر التصريف بالماء. وإذا وجدنا كسرًا أو ميولًا غير صحيحة في الخط نخبرك قبل أي عمل إضافي.

في حالات الطفح أو الروائح القوية اتصل بنا مباشرة، فخدمة الطوارئ متاحة على مدار الساعة.',
  'We clear blocked bathroom, kitchen and floor drains, and the lines between rooms up to the inspection chamber, using drain rods and machines.

We find the blockage first, clear it and test the flow with water. If we find a broken pipe or a wrong fall in the line, we tell you before any extra work.

For overflowing drains or strong smells, call us straight away — emergency service is available 24/7.',
  array['تحديد مكان الانسداد', 'التسليك بالأدوات أو مكينة التسليك', 'تنظيف الصفاية وغرفة التفتيش القريبة', 'اختبار التصريف بعد الانتهاء']::text[],
  array['Locating the blockage', 'Clearing with rods or a drain machine', 'Cleaning the floor drain and nearby inspection chamber', 'Flow test when finished']::text[],
  array['شفط البيارة (يحتاج صهريجًا)', 'تكسير مواسير الصرف وتغييرها']::text[],
  array['Septic tank pumping (needs a tanker)', 'Breaking out and replacing drain pipes']::text[],
  '{}'::text[],
  '{}'::text[],
  array['صفايات أرضية وأغطيتها', 'سيفونات ووصلات صرف']::text[],
  array['Floor drains and covers', 'Traps and drain fittings']::text[],
  true,
  null,
  null,
  null,
  '[{"q_ar":"هل يعود الانسداد مرة أخرى؟","a_ar":"إذا كان السبب دهونًا أو أوساخًا فالتسليك يحلّه. وإذا كان السبب في ميول الخط أو كسر فيه، نخبرك بالحل المناسب قبل أي عمل.","q_en":"Will the blockage come back?","a_en":"If it was caused by grease or debris, clearing it solves the problem. If the line has a wrong fall or a break, we explain the right fix before doing anything."}]'::jsonb,
  true,
  true,
  130,
  true
)
