insert into public.services (category_id, slug, name_ar, name_en, short_ar, short_en, body_ar, body_en, includes_ar, includes_en, excludes_ar, excludes_en, options_ar, options_en, parts_ar, parts_en, parts_in_stock, wa_message_ar, wa_message_en, image_url, faq, has_detail_page, featured, sort_order, is_active)
values (
  (select id from public.categories where slug = 'electrical'),
  'spotlight-installation-replacement',
  'تركيب وتغيير سبوت لايت',
  'Spotlight installation & replacement',
  'تركيب سبوت لايت جديد مع قص الجبس أو تغيير القديم، بجميع المقاسات الشائعة من 7 إلى 20 سم تقريبًا.',
  'New spotlights with gypsum cut-out, or replacing old ones — all common sizes from about 7 to 20 cm.',
  'نركّب سبوت لايت جديدًا في أسقف الجبس مع قص الفتحة بالمقاس الصحيح، أو نغيّر السبوتات القديمة والمحروقة بسبوتات ليد جديدة من محلنا.

نوفّر جميع المقاسات الشائعة من 7 سم إلى 20 سم تقريبًا، بأحجام صغيرة ووسط وكبيرة، وبألوان إضاءة مختلفة: أبيض ودافئ ومحايد.

أرسل لنا المقاس والعدد عبر واتساب، أو صورة للسقف، ونؤكد لك السعر قبل البدء.',
  'We install new spotlights in gypsum ceilings, cutting the opening to the right size, or replace old and burnt-out spotlights with new LED ones from our shop.

We stock all common sizes from about 7 cm to 20 cm — small, medium and large — in different light colours: cool white, warm and neutral.

Send us the size and how many on WhatsApp, or a photo of the ceiling, and we confirm the price before we start.',
  array['قص فتحات الجبس للتركيب الجديد', 'تركيب السبوت وتوصيله', 'تغيير السبوتات القديمة بنفس المقاس', 'تجربة الإنارة بعد التركيب']::text[],
  array['Cutting gypsum openings for new spotlights', 'Fitting and wiring the spotlight', 'Replacing old spotlights in the same size', 'Testing the lights afterwards']::text[],
  array['تمديد أسلاك جديدة من الطبلون', 'إصلاح الجبس أو دهانه']::text[],
  array['Running new cables from the breaker panel', 'Gypsum repairs or painting']::text[],
  array['صغير، وسط، وكبير', 'جميع المقاسات الشائعة من 7 سم إلى 20 سم تقريبًا', 'تركيب جديد مع قص الجبس', 'تغيير سبوت قديم بنفس المقاس']::text[],
  array['Small, medium and large', 'All common sizes from about 7 cm to 20 cm', 'New installation with gypsum cut-out', 'Replacing an existing spotlight in the same size']::text[],
  array['سبوت لايت ليد بمقاسات من 7 إلى 20 سم تقريبًا', 'ألوان إضاءة: أبيض ودافئ ومحايد', 'محولات (درايفر) ووصلات']::text[],
  array['LED spotlights from about 7 to 20 cm', 'Light colours: cool white, warm and neutral', 'Drivers and connectors']::text[],
  true,
  null,
  null,
  null,
  '[{"q_ar":"ماذا لو كان مقاس الفتحة القديمة مختلفًا؟","a_ar":"نوسّع الفتحة إذا كان السبوت الجديد أكبر، أو نركّب سبوتًا بمقاس يناسب الفتحة الحالية. أرسل لنا صورة ونقترح الأنسب.","q_en":"What if the old opening is a different size?","a_en":"We widen the opening if the new spotlight is bigger, or fit one that matches the existing opening. Send us a photo and we’ll suggest the best fit."},{"q_ar":"هل تحضرون السبوتات معكم؟","a_ar":"نعم، السبوتات متوفرة في محلنا بمقاسات وألوان مختلفة، ويحضرها الفني معه حسب طلبك.","q_en":"Do you bring the spotlights?","a_en":"Yes. Spotlights in many sizes and colours are in stock at our shop, and the technician brings what you ask for."}]'::jsonb,
  true,
  true,
  10,
  true
)
on conflict (category_id, slug) do nothing;

insert into public.services (category_id, slug, name_ar, name_en, short_ar, short_en, body_ar, body_en, includes_ar, includes_en, excludes_ar, excludes_en, options_ar, options_en, parts_ar, parts_en, parts_in_stock, wa_message_ar, wa_message_en, image_url, faq, has_detail_page, featured, sort_order, is_active)
values (
  (select id from public.categories where slug = 'electrical'),
  'surface-panel-light',
  'تركيب وتغيير بانيل سطحي',
  'Surface panel light installation & replacement',
  'تركيب بانيل ليد سطحي دائري أو مربع، من الصغير إلى الكبير، أو تغيير القديم.',
  'Installing or replacing surface-mounted LED panels — round or square, small to large.',
  'البانيل السطحي يُركّب على السقف مباشرة دون فتحة في الجبس، ويناسب الغرف والممرات والمطابخ. نركّب البانيل الدائري أو المربع بأحجام من الصغير إلى الكبير.

نثبّت البانيل ونوصله ونجرّبه، ويمكننا تغيير البانيل القديم في نفس المكان.',
  'A surface panel mounts straight onto the ceiling with no gypsum cut-out — ideal for rooms, corridors and kitchens. We install round or square panels from small to large.

We fix, wire and test the panel, and can replace an old panel in the same spot.',
  array['تثبيت البانيل على السقف', 'التوصيل الكهربائي', 'تغيير البانيل القديم', 'تجربة الإنارة']::text[],
  array['Fixing the panel to the ceiling', 'Electrical connection', 'Replacing the old panel', 'Light test']::text[],
  array['تمديد نقطة إنارة جديدة من مكان بعيد', 'إصلاح الجبس أو دهانه']::text[],
  array['A new light point run from far away', 'Gypsum repairs or painting']::text[],
  array['دائري أو مربع', 'من الصغير إلى الكبير']::text[],
  array['Round or square', 'Small to large']::text[],
  array['بانيل ليد سطحي دائري ومربع', 'ألوان إضاءة مختلفة', 'وصلات وبراغي تثبيت']::text[],
  array['Round and square surface LED panels', 'Different light colours', 'Connectors and fixings']::text[],
  true,
  null,
  null,
  null,
  '[{"q_ar":"ما الفرق بين البانيل السطحي والغاطس؟","a_ar":"السطحي يُركّب فوق السقف دون قص، أما الغاطس فيحتاج فتحة في الجبس. إذا كانت عندك فتحة قديمة أخبرنا لنختار المناسب.","q_en":"What is the difference between surface and recessed panels?","a_en":"A surface panel mounts on the ceiling without cutting; a recessed one needs a gypsum opening. If you already have an opening, tell us and we’ll pick the right one."}]'::jsonb,
  true,
  true,
  20,
  true
)
on conflict (category_id, slug) do nothing;

