  array['Safely isolating the circuit', 'Fitting the new socket or replacing the damaged one', 'Wiring and earthing check', 'Testing the socket afterwards']::text[],
  array['تمديد خط جديد لمسافة طويلة داخل الجدار', 'إصلاح البلاط أو الدهان حول الفيش']::text[],
  array['A new cable run over a long distance inside the wall', 'Tile or paint repairs around the socket']::text[],
