  array['مفاتيح رئيسية بقدرات مختلفة', 'مفاتيح فرعية', 'أطراف توصيل ومثبّتات']::text[],
  array['Main breakers in different ratings', 'Sub-circuit breakers', 'Terminals and fixings']::text[],
